/**
 * How it works: numbered or icon steps in a row or a column. Axes: layout (row, column), marker (number, icon),
 * align, density, tone.
 */
import { type ReactNode } from "react";
import { IconBadge } from "../primitives/iconbadge/iconbadge";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { SectionFrame } from "../components/section-frame";
import { cn } from "../utils";
import type { Step } from "./steps-list.types";

export type StepsListProps = {
  id: string;
  title: string;
  steps: Step[];
  layout?: "row" | "column";
  marker?: "number" | "icon";
  align?: "start" | "center";
  tone?: "default" | "muted";
  density?: "roomy" | "default" | "compact";
};

export function StepsList({
  id,
  title,
  steps,
  layout = "row",
  marker = "number",
  align = "start",
  tone = "default",
  density = "default",
}: StepsListProps) {
  return (
    <SectionFrame
      id={id}
      title={title}
      tone={tone}
      density={density}
      align={align}
      measure={(((layout as string) === "row") ? "default" : "2xl")}
    >
      <List
        tag="ol"
        className={cn(
          "grid gap-6",
          (((layout as string) === "row") ? "sm:grid-cols-2 md:grid-cols-4" : "")
        )}
        data-testid="items"
      >
        {(steps ?? []).map((step, i) => (
          <ListItem key={step.id}
            className={cn(
              "flex gap-4",
              (((layout as string) === "row") ? "flex-col" : ""),
              (((align as string) === "center") ? "items-center text-center" : "")
            )}
            data-testid="item"
          >
            <IconBadge variant="primary" data-slot="marker">
              {((marker as string) === "icon") ? (
                <LucideIcon name={step.icon} size={20} />
              ) : (
                <Text size="base" weight="bold">
                  {((i + 1) == null ? undefined : String((i + 1)))}
                </Text>
              )}
            </IconBadge>
            <Stack gap="2" align={(((align as string) === "center") ? "center" : "start")}>
              <Title as={3} size="xl" weight="bold">
                {step.title}
              </Title>
              <Text size="sm" className="text-muted-foreground">
                {step.text}
              </Text>
            </Stack>
          </ListItem>
        ))}
      </List>
    </SectionFrame>
  );
}

